ALTER TABLE "Quotation" ADD COLUMN "customerId" UUID, ADD COLUMN "currentVersionId" UUID, ADD COLUMN "exchangeRateSnapshot" DECIMAL(20,6) NOT NULL DEFAULT 1, ADD COLUMN "validFrom" TIMESTAMP(3), ADD COLUMN "validUntil" TIMESTAMP(3), ADD COLUMN "subtotal" DECIMAL(20,2) NOT NULL DEFAULT 0, ADD COLUMN "discountAmount" DECIMAL(20,2) NOT NULL DEFAULT 0, ADD COLUMN "discountPercent" DECIMAL(9,4) NOT NULL DEFAULT 0, ADD COLUMN "taxAmount" DECIMAL(20,2) NOT NULL DEFAULT 0, ADD COLUMN "shippingAmount" DECIMAL(20,2) NOT NULL DEFAULT 0, ADD COLUMN "installationAmount" DECIMAL(20,2) NOT NULL DEFAULT 0, ADD COLUMN "warrantyAmount" DECIMAL(20,2) NOT NULL DEFAULT 0, ADD COLUMN "grandTotal" DECIMAL(20,2) NOT NULL DEFAULT 0, ADD COLUMN "sentAt" TIMESTAMP(3), ADD COLUMN "acceptedAt" TIMESTAMP(3), ADD COLUMN "rejectedAt" TIMESTAMP(3), ADD COLUMN "expiredAt" TIMESTAMP(3), ADD COLUMN "updatedBy" UUID;
UPDATE "Quotation" q SET "customerId"=p."customerId", "updatedBy"=q."createdBy" FROM "Project" p WHERE p."id"=q."projectId";
ALTER TABLE "Quotation" ALTER COLUMN "customerId" SET NOT NULL, ALTER COLUMN "updatedBy" SET NOT NULL;
ALTER TABLE "QuotationVersion" ADD COLUMN "installationTerms" TEXT, ADD COLUMN "notes" TEXT, ADD COLUMN "shipping" DECIMAL(20,2) NOT NULL DEFAULT 0, ADD COLUMN "installation" DECIMAL(20,2) NOT NULL DEFAULT 0, ADD COLUMN "warranty" DECIMAL(20,2) NOT NULL DEFAULT 0, ADD COLUMN "sentAt" TIMESTAMP(3), ADD COLUMN "rejectedAt" TIMESTAMP(3);
CREATE TABLE "QuotationSection" ("id" UUID NOT NULL,"quotationVersionId" UUID NOT NULL,"title" TEXT NOT NULL,"position" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "QuotationSection_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QuotationTerm" ("id" UUID NOT NULL,"quotationVersionId" UUID NOT NULL,"termType" TEXT NOT NULL,"content" TEXT NOT NULL,"position" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "QuotationTerm_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QuotationApproval" ("id" UUID NOT NULL,"quotationVersionId" UUID NOT NULL,"actorId" UUID NOT NULL,"decision" TEXT NOT NULL,"comment" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "QuotationApproval_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QuotationDocument" ("id" UUID NOT NULL,"quotationVersionId" UUID NOT NULL,"language" TEXT NOT NULL,"format" TEXT NOT NULL,"storageKey" TEXT NOT NULL,"checksum" TEXT NOT NULL,"generatedBy" UUID NOT NULL,"generatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "QuotationDocument_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QuotationStatusHistory" ("id" UUID NOT NULL,"quotationVersionId" UUID NOT NULL,"fromStatus" TEXT,"toStatus" TEXT NOT NULL,"actorId" UUID NOT NULL,"comment" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "QuotationStatusHistory_pkey" PRIMARY KEY ("id"));
CREATE INDEX "QuotationSection_quotationVersionId_position_idx" ON "QuotationSection"("quotationVersionId","position");
CREATE INDEX "QuotationTerm_quotationVersionId_position_idx" ON "QuotationTerm"("quotationVersionId","position");
CREATE INDEX "QuotationApproval_quotationVersionId_createdAt_idx" ON "QuotationApproval"("quotationVersionId","createdAt");
CREATE INDEX "QuotationDocument_quotationVersionId_generatedAt_idx" ON "QuotationDocument"("quotationVersionId","generatedAt");
CREATE INDEX "QuotationStatusHistory_quotationVersionId_createdAt_idx" ON "QuotationStatusHistory"("quotationVersionId","createdAt");
ALTER TABLE "QuotationSection" ADD CONSTRAINT "QuotationSection_quotationVersionId_fkey" FOREIGN KEY ("quotationVersionId") REFERENCES "QuotationVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "QuotationTerm" ADD CONSTRAINT "QuotationTerm_quotationVersionId_fkey" FOREIGN KEY ("quotationVersionId") REFERENCES "QuotationVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "QuotationApproval" ADD CONSTRAINT "QuotationApproval_quotationVersionId_fkey" FOREIGN KEY ("quotationVersionId") REFERENCES "QuotationVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "QuotationDocument" ADD CONSTRAINT "QuotationDocument_quotationVersionId_fkey" FOREIGN KEY ("quotationVersionId") REFERENCES "QuotationVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "QuotationStatusHistory" ADD CONSTRAINT "QuotationStatusHistory_quotationVersionId_fkey" FOREIGN KEY ("quotationVersionId") REFERENCES "QuotationVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
